from math import sqrt, floor, ceil

def min_route(n):
	(ls, us) = (floor(sqrt(n)), ceil(sqrt(n)))
	p1 = 4 * ls + 2
	p2 = 4 * us
	if ls < n - ls ** 2:
		return p2
	return min(p1, p2)

def main():
	n = int(input().strip())
	print(min_route(n))
