def check_chord(tup):
	notes = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'B', 'H']
	notes += notes
	(x, y, z) = tup
	x_y = 0
	y_z = 0
	for i in range(notes.index(x), len(notes)):
		if notes[i] == y:
			break
		else:
			x_y += 1
	for i in range(notes.index(y), len(notes)):
		if notes[i] == z:
			break
		else:
			y_z += 1
	if x_y == 4 and y_z == 3:
		return 'major'
	elif x_y == 3 and y_z == 4:
		return 'minor'
	else:
		return 'strange'

