@functools.lru_cache(10000)
def dp(x, y):
	now = (x, y)
	if x < 10:
		first = 1 if x or y else 0
		return (first, x - max(x, y))
	mod = 1
	while mod <= x // 10:
		mod *= 10
	maxDig = x // mod
	part1 = dp(x % mod, max(maxDig, y))
	part2 = dp(x - x % mod + part1[1], y)
	return (part1[0] + part2[0], part2[1])

