	lo = 0
	hi = len(gh)
	ans = 0
	while lo <= hi:
		mid = (lo + hi) // 2
		if gh[mid] >= a:
			ans = gh[mid]
			hi = mid - 1
		else:
			lo = mid + 1
	return ans
