			pairs_map[u].add(v)
		if v not in pairs_map:
			pairs_map[v] = set((u,))
		else:
			pairs_map[v].add(u)
	for triple in combinations(range(1, len(prices) + 1), r=3):
		score = 0
		(t1, t2, t3) = triple
		if t1 in pairs_map and t2 in pairs_map[t1] and (t3 in pairs_map[t1]):
			score += 1
		if t2 in pairs_map and t1 in pairs_map[t2] and (t3 in pairs_map[t2]):
			score += 1
		if t3 in pairs_map and t1 in pairs_map[t3] and (t2 in pairs_map[t3]):
			score += 1
		if score == 3:
			triples.append(triple)
	min_price = sys.maxsize
	for triple in triples:
		total_price = prices_map[triple[0]] + prices_map[triple[1]] + prices_map[triple[2]]
