def digisum(n):
	sum = 0
	while n != 0:
		sum += n % 10
		n = n // 10
	return sum

def give9(n):
	num9 = 0
	while n >= 10:
		num9 = num9 * 10 + 9
		n = n // 10
	return num9

def method3(n):
	a = give9(n)
	b = n - a
	return digisum(a) + digisum(b)
n = int(input())
print(method3(n))

