		cleans = 0
		(bowls, plates) = (self.n_m_k[1], self.n_m_k[2])
		for day in self.plan:
			if day == 1:
				if bowls:
					bowls -= 1
				else:
					cleans += 1
			elif plates:
				plates -= 1
			elif bowls:
				bowls -= 1
			else:
				cleans += 1
		self.result = str(cleans)

	def get_result(self):
		return self.result
